-- Additive preview PoC namespace; existing citizen data is preserved.
CREATE TABLE IF NOT EXISTS poc_elections (id TEXT PRIMARY KEY,nation_id TEXT NOT NULL CHECK(nation_id='kindle'),candidates_json TEXT NOT NULL CHECK(json_valid(candidates_json) AND json_array_length(candidates_json)=3),opens_at INTEGER NOT NULL,closes_at INTEGER NOT NULL,closed_at INTEGER,result_json TEXT,CHECK(closes_at=opens_at+259200),CHECK(closed_at IS NULL OR closed_at>=closes_at),CHECK(result_json IS NULL OR (closed_at IS NOT NULL AND json_valid(result_json))));
CREATE TABLE IF NOT EXISTS poc_voter_receipts (election_id TEXT NOT NULL REFERENCES poc_elections(id),clerk_user_id TEXT NOT NULL REFERENCES citizens(clerk_user_id),request_id TEXT NOT NULL UNIQUE,checked_at INTEGER NOT NULL,ballot_written INTEGER NOT NULL DEFAULT 0 CHECK(ballot_written IN (0,1)),policy TEXT NOT NULL CHECK(policy='preview-citizen-v1'),PRIMARY KEY(election_id,clerk_user_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS poc_anonymous_ballots (id TEXT PRIMARY KEY,election_id TEXT NOT NULL REFERENCES poc_elections(id),ranking_json TEXT NOT NULL CHECK(json_valid(ranking_json) AND json_array_length(ranking_json)=3),policy TEXT NOT NULL CHECK(policy='preview-citizen-v1')) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS idx_poc_ballots_election ON poc_anonymous_ballots(election_id);
